from collections import deque, defaultdict

def clusters(I,bg):
    H,W=len(I),len(I[0]); seen=set()
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cl=[]
                while q:
                    a,b=q.popleft(); cl.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==I[a][b] and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                yield I[a][b],sorted(cl)

def solve_greedy(I,O=None):
    bg=I[0][0]
    cs=list(clusters(I,bg))
    occ={}
    for v,c in cs:
        base=min(a for a,_ in c); b0=min(b for _,b in c)
        h=max(a for a,_ in c)-base+1; w=max(b for _,b in c)-b0+1
        r=0; cc=0
        # slide diagonally up-left; but only move when BOTH free? earlier failure: color3 at(0,0). Allow blocking by anything? Use: keep moving until hitting occupied OR boundary.
        while True:
            nr,nc=r-1,cc-1
            if nr>=0 and nc>=0 and all((nr+a,nc+b) not in occ or (nr+a,nc+b)==v for a in range(h) for b in range(w)):
                r,cc=nr,nc
            else: break
        pl={(r+a-base,cc+b-b0) for a,b in c}
        bad=[p for p in pl if p in occ and occ[p]!=v]
        assert not bad, f'collision color{v} at({r},{cc}) shape({h},{w}) bad{bad}'
        for p in pl: occ[p]=v
    rs=[p[0] for p in occ]; cls_=[p[1] for p in occ]
    out=[[bg]*(max(cls_)-min(cls_)+1) for _ in range(min(rs),max(rs)+1)]
    for (r_,c_),v in occ.items(): out[r_-min(rs)][c_-min(cls_)]=v
    return out

