# Group by color with uniform shift; pick per-color shift via min-bbox, then tie-break by sum |dr|+|dc| ascending, then by color index.
def candidates(I):
    bg=I[0][0]
    # group cells by color
    bycolor=defaultdict(set)
    for v,c in clusters(I,bg):
        for p in c: bycolor[v].add(p)
    out={}
    for v in sorted(bycolor):
        cells=list(bycolor[v])
        best=None
        for dr in range(-max(a for a,_ in cells)-1, max(a for a,_ in cells)+2):
            for dc in range(-max(b for _,b in cells)-1, max(b for _,b in cells)+2):
                rs=[p[0]+dr for p in cells]; cs_=[p[1]+dc for p in cells]
                r0,r1=min(rs),max(rs); c0,c1=min(cs_),max(cs_)
                if (r1-r0+1)*(c1-c0+1)<len(cells): continue
                area=(r1-r0+1)*(c1-c0+1)
                if best is None or area<best[0]:
                    best=(area,(abs(dr)+abs(dc)),v,dr,dc,cells)
        if best:
            a,ti,vv,dr,dc,cells=best
            out[v]=(dr,dc,cells)
    return out,out

