import numpy as np
# Solve piece assignment: for each demo, find for each output component the best matching input component
# (by shape equality, allowing rotation/reflection), report translation.
def normcomp(g):
    seen=set(); out=[]
    H,W=len(g),len(g[0]); bg=g[0][0]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    x,y=st.pop(); comp.append((x,y,col))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and g[nx][ny]==col:
                                seen.add((nx,ny)); st.append((nx,ny))
                rs=[a for a,b,v in comp]; cs=[b for a,b,v in comp]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                sub=np.zeros((h,w),int)
                for a,b,v in comp: sub[a-min(rs)][b-min(cs)]=v
                out.append({'cells':set(comp),'sub':sub,'h':h,'w':w})
    return out
