    vals,cnt=np.unique(gi,return_counts=True); bg=vals[np.argmax(cnt)]
    seeds=[(i,j) for i in range(gi.shape[0]) for j in range(gi.shape[1]) if gi[i,j]!=bg]
    pred=np.zeros_like(go,bool)
    for (si,sj) in seeds:
        for di,dj in [(1,1),(1,-1)]:
            for step in range(-max(si,sj)+min(si,sj), max((H:=gi.shape[0])-si+(W:=gi.shape[1])-sj, -1)):
                pass
        # collect
        cells=[]
        for k in range(0,max(H,W)+1):
            cells.append((si+k,sj+k)); cells.append((si+k,sj-k))
        for c in cells:
            if 0<=c[0]<H and 0<=c[1]<W: pred[c]=True
    print(p,'nseeds',len(seeds),'pred==five:',np.array_equal(pred,(go==5)))
